function updateLegacyLabels(root){
 const walker=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT);
 const found=[]; let n;
 while((n=walker.nextNode())) if(n.nodeValue&&n.nodeValue.includes('Campbell-Walsh-Wein Urology 12e')) found.push(n);
 found.forEach(x=>{x.nodeValue=x.nodeValue.replace(/Campbell-Walsh-Wein Urology 12e/g,'Campbell-Walsh-Wein Urology 13e (reference layer; migration tracked)');});
}
