 if(!sel.options.length){sel.innerHTML='<option value="all">All mapped clinical modules</option>'+MODULES.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.name)+'</option>').join('')+'<option value="index">Full chapter index</option>';sel.value='all';}
 const status=$('cw13Status');
 if(status){const mapped=CHAPTERS.filter(c=>COVERED_CHAPTERS.has(c.chapter)&&!c.electronicOnly&&c.chapter!==96).length;const tocOnly=CHAPTERS.filter(c=>(c.coverageStatus||'').startsWith('TOC index only')).length;const synthesized=CHAPTERS.filter(c=>(c.coverageStatus||'').startsWith('Chapter-specific original synthesis added')).length;status.textContent=CHAPTERS.length+' chapters indexed • '+MODULES.length+' topic modules • '+synthesized+' chapter-specific original syntheses • '+mapped+' chapters cross-referenced to broader topic summaries/checklists • '+tocOnly+' chapters currently TOC-only.';}
 $('cw13Search').oninput=render;$('cw13Module').onchange=render;
